begin;
select pg_advisory_xact_lock(hashtext('geostats-v16.3.4-runtime-catalog'));
create table public.category_recovery_evidence_v16_3_4 (
  category_id text primary key references public.stat_categories(id) on delete cascade,
  rules_version text not null,
  snapshot_fingerprint text not null,
  dependency_fingerprints jsonb not null,
  proofs jsonb not null,
  allow_quality_floor boolean not null default false,
  credibility_reason text,
  rationale text not null,
  previous_state jsonb not null,
  approved boolean not null default false,
  assessed_at timestamptz not null default now(),
  check(jsonb_typeof(proofs)='array'),
  check(jsonb_typeof(dependency_fingerprints)='object')
);
alter table public.category_recovery_evidence_v16_3_4 enable row level security;
revoke all on public.category_recovery_evidence_v16_3_4 from public,anon,authenticated;
grant select,insert,update on public.category_recovery_evidence_v16_3_4 to service_role;

-- Bind exceptions to source identity, observations, units and gameplay semantics.
-- Editorial notes/retrieval timestamps do not affect board validity.
create function public.category_recovery_fingerprint_v16_3_4(p_id text)
returns text language sql stable security definer set search_path='' set extra_float_digits='3' as $$
select md5(jsonb_build_array(
 c.id,c.source_organization,c.source_indicator_code,c.common_year,c.ranking_direction,
 c.unit,c.value_type,c.measurement_type,c.title,c.plain_language_description,
 c.semantic_family,c.concept_group,c.semantic_topic,c.eligible_universe_type,
 c.eligible_country_iso3,c.eligible_country_count,c.minimum_year,
 c.metadata->'semanticFamily',c.metadata->'semanticTopic',c.metadata->'strategyFamily',
 c.metadata->'broadDomain',c.metadata->'knowledgeCluster',c.metadata->'stable_decimals',
 coalesce((select jsonb_agg(jsonb_build_array(o.country_iso3,o.value) order by o.country_iso3)
 from public.stat_observations o where o.category_id=c.id and o.data_year=c.common_year),'[]'::jsonb)
)::text) from public.stat_categories c where c.id=p_id
$$;
create function public.category_recovery_ready_v16_3_4(p_id text)
returns boolean language sql stable security definer set search_path='' as $$
select coalesce((select e.approved and e.rules_version='16.3.4'
 and e.snapshot_fingerprint=public.category_recovery_fingerprint_v16_3_4(e.category_id)
 and jsonb_array_length(e.proofs)=3
 and (select count(distinct p->>'difficulty')=3 and bool_and((p->>'reachable')::boolean)
      from jsonb_array_elements(e.proofs) p
      where p->>'difficulty' in ('easy','normal','expert'))
 and not exists(select 1 from jsonb_each_text(e.dependency_fingerprints) d
                where d.value is distinct from public.category_recovery_fingerprint_v16_3_4(d.key))
 from public.category_recovery_evidence_v16_3_4 e where e.category_id=p_id),false)
$$;
create function public.category_recovery_quality_exception_v16_3_4(p_id text)
returns boolean language sql stable security definer set search_path='' as $$
select coalesce((select e.allow_quality_floor and public.category_recovery_ready_v16_3_4(p_id)
 from public.category_recovery_evidence_v16_3_4 e where e.category_id=p_id),false)
$$;
create function public.apply_category_recovery_credibility_v16_3_4()
returns void language sql security definer set search_path='' as $$

 update public.stat_categories c set
 credibility_score=case when e.credibility_reason is not null then 75 else c.credibility_score end,
 credibility_status=case when e.credibility_reason is not null then 'caution' else c.credibility_status end,
 credibility_reason=coalesce(e.credibility_reason,c.credibility_reason),
 content_review_status='approved',curation_status='approved',player_quality_status='approved',
 content_review_reason='v16.3.4 reviewed recovery: source-audited, clear copy, nonduplicate, current solver witness.',
 player_quality_reason='v16.3.4 reviewed recovery: current complete board witnesses replace obsolete pending/rewrite labels.',
 metadata=coalesce(c.metadata,'{}'::jsonb)||case when e.credibility_reason is not null
 then jsonb_build_object('credibilityScore',75,'credibilityStatus','caution','credibilityReason',e.credibility_reason)
 else '{}'::jsonb end
 from public.category_recovery_evidence_v16_3_4 e
 where c.id=e.category_id and public.category_recovery_ready_v16_3_4(c.id)
 and c.validation_status='verified'
 and coalesce(c.validation_mismatch_count,0)=0 and coalesce(c.validation_ranking_mismatch_count,0)=0
$$;
revoke all on function public.category_recovery_fingerprint_v16_3_4(text),public.category_recovery_ready_v16_3_4(text),
public.category_recovery_quality_exception_v16_3_4(text),public.apply_category_recovery_credibility_v16_3_4() from public,anon,authenticated;
grant execute on function public.category_recovery_fingerprint_v16_3_4(text),public.category_recovery_ready_v16_3_4(text),
public.category_recovery_quality_exception_v16_3_4(text),public.apply_category_recovery_credibility_v16_3_4() to service_role;

