rld Bank","indicator":"SH.XPD.CHEX.PC.CD","year":2023,"direction":"high","count":191,"hash":"c1b9b8633a6448a057d3fd88401f90ea"},{"id":"infantMortality","source":"World Bank","indicator":"SP.DYN.IMRT.IN","year":2024,"direction":"low","count":193,"hash":"188359fc8c3b6615c18ed9c25fa87e79"},{"id":"life","source":"World Bank","indicator":"SP.DYN.LE00.IN","year":2024,"direction":"high","count":194,"hash":"af423e041bc80b44f71b9efdef975fb2"},{"id":"fertility","source":"World Bank","indicator":"SP.DYN.TFRT.IN","year":2024,"direction":"high","count":194,"hash":"1ded32d234d223855e945fa3e7641e7c"},{"id":"young","source":"World Bank","indicator":"SP.POP.0014.TO.ZS","year":2025,"direction":"high","count":194,"hash":"f467fa23ced5858035f25982a9fe0099"},{"id":"older","source":"World Bank","indicator":"SP.POP.65UP.TO.ZS","year":2025,"direction":"high","count":194,"hash":"503f2e5754ebeae9fd26cc2d4943f5f8"},{"id":"populationGrowth","source":"World Bank","indicator":"SP.POP.GROW","year":2025,"direction":"high","count":194,"hash":"7d407528036e58e6a63e99ddf9da9f75"},{"id":"population","source":"World Bank","indicator":"SP.POP.TOTL","year":2025,"direction":"high","count":194,"hash":"6713740e9b782f257c3e457a82c30218"},{"id":"rural","source":"World Bank","indicator":"SP.RUR.TOTL.ZS","year":2025,"direction":"high","count":194,"hash":"22fab7741a3ea7e68cb62b495ab887b5"},{"id":"foodImportsShare","source":"World Bank","indicator":"TM.VAL.FOOD.ZS.UN","year":2024,"direction":"high","count":126,"hash":"7519195331bfcb9d0ec18ea7b480b218"},{"id":"merchImports","source":"World Bank","indicator":"TM.VAL.MRCH.CD.WT","year":2025,"direction":"high","count":190,"hash":"9286adbd3eee281e8a8b6751930f2b94"},{"id":"foodExportsShare","source":"World Bank","indicator":"TX.VAL.FOOD.ZS.UN","year":2024,"direction":"high","count":126,"hash":"7ec4d97c8c06602ea668fcb45ec29e19"},{"id":"merchExports","source":"World Bank","indicator":"TX.VAL.MRCH.CD.WT","year":2025,"direction":"high","count":190,"hash":"330c204365b3139a50ddd64682a53508"},{"id":"highTechExports","source":"World Bank","indicator":"TX.VAL.TECH.CD","year":2024,"direction":"high","count":121,"hash":"ad956b7c5b34e38aa62e70d8deb8e412"}]$snapshot$::jsonb) x;
create temporary table recovery_baseline on commit drop as
select id from public.category_runtime_review_v16_2 where computed_playable_v16_2;
do $checks$ begin
 if (select count(*) from recovery_baseline)<>318 then raise exception 'Baseline changed; re-audit required'; end if;
 if (select count(*) from recovery_proposals)<>67 then raise exception 'Expected 67 reviewed candidates'; end if;
 if exists(select 1 from recovery_snapshot s left join public.stat_categories c on c.id=s.id
 where c.id is null or c.source_organization is distinct from s.snapshot->>'source'
 or c.source_indicator_code is distinct from s.snapshot->>'indicator'
 or c.common_year is distinct from (s.snapshot->>'year')::integer
 or c.ranking_direction is distinct from s.snapshot->>'direction')
 then raise exception 'Source identity/year changed since solver export'; end if;
 if exists(select 1 from recovery_snapshot s where (s.snapshot->>'count')::integer <>
  (select count(*) from public.stat_observations o where o.category_id=s.id and o.data_year=(s.snapshot->>'year')::integer)
  or s.snapshot->>'hash' is distinct from
  (select md5(string_agg(o.country_iso3||':'||encode(float8send(o.value::double precision),'hex'),',' order by o.country_iso3))
   from public.stat_observations o where o.category_id=s.id and o.data_year=(s.snapshot->>'year')::integer)) then raise exception 'Observations changed since solver export'; end if;
 if exists(select 1 from recovery_proposals p join public.category_runtime_review_v16_2 v on v.id=p.id
 where v.editorial_status in ('rejected','duplicate') or v.duplicate_of is not null
 or v.validation_mismatch_count<>0 or v.validation_ranking_mismatch_count<>0
 or v.stale_data or v.subjective_or_composite or v.political_self_reported
 or v.confusing or v.esoteric or v.poor_coverage or v.objective_status<>'objective')
 then raise exception 'Protected or invalid candidate in recovery batch'; end if;
end $checks$;

-- Explicit user-directed generous editorial review; no reviewer identity is fabricated.
insert into public.category_recovery_evidence_v16_3_4
(category_id,rules_version,snapshot_fingerprint,dependency_fingerprints,proofs,allow_quality_floor,credibility_reason,rationale,previous_state)
select p.id,'16.3.4','pending','{}'::jsonb,p.proposal->'proofs',(p.proposal->>'quality')::boolean,
p.proposal->>'credibility_reason',
'Owner requested maximum defensible nonduplicate catalog. Recovered by explicit copy/unit corrections and real production-solver witnesses; no country observations, scores, or historical boards were changed.',
jsonb_build_object('category',to_jsonb(c),'review',to_jsonb(r))
from recovery_proposals p join public.stat_categories c on c.id=p.id
join public.category_review_state r on r.category_id=p.id;

insert into public.category_review_contracts_v16_3_4 as contract(category_id,review_patch,presentation_patch)
select p.id,jsonb_strip_nulls(jsonb_build_object('status','approved','recommended_title',p.proposal->'patch'->'title')),
jsonb_strip_nulls((p.proposal->'patch')-'unit'-'value_type') ||
 case when p.proposal->'patch' ? 'plain_language_description'
 then jsonb_build_object('metadata',jsonb_build_object('boardDescription',p.proposal->'patch'->'plain_language_description'))
 else '{}'::jsonb end
from recovery_proposals p
on conflict(category_id) do update set review_patch=contract.review_patch||excluded.review_patch,
presentation_patch=contract.presentation_patch||excluded.presentation_patch,
revision=contract.revision+1,updated_at=now();

update public.stat_categories c set
 title=coalesce(p.proposal->'patch'->>'title',c.title),
 short_title=coalesce(p.proposal->'patch'->>'short_title',c.short_title),
 plain_language_description=coalesce(p.proposal->'patch'->>'plain_language_description',c.plain_language_description),
 unit=coalesce(p.proposal->'patch'->>'unit',c.unit),
 value_type=coalesce(p.proposal->'patch'->>'value_type',c.value_type),
 measurement_type=coalesce(p.proposal->'patch'->>'measurement_type',c.measurement_type),
 content_review_status='approved',curation_status='approved',player_quality_status='approved',
 content_review_reason='v16.3.4 maximum recovery: clear source-qualified copy, reviewed data and solver witnesses.',
 metadata=coalesce(c.metadata,'{}'::jsonb)
 || case when p.proposal->'patch' ? 'plain_language_description' then jsonb_build_object('boardDescription',p.proposal->'patch'->>'plain_language_description') else '{}'::jsonb end
 || case when p.proposal->'patch' ? 'unit' then jsonb_build_object('unitExplanation',p.proposal->'patch'->>'unit') else '{}'::jsonb end,
 updated_at=now()
from recovery_proposals p where c.id=p.id;

update public.category_review_state r set status='approved',updated_at=now()
from recovery_proposals p where r.category_id=p.id;

-- Only dimensionless replacements of generic historical rejections are cleared.
-- Explicit owner exclusions and all original ledger records remain intact.
do $legacy$ begin
 if exists(select 1 from recovery_proposals p cross join lateral jsonb_array_elements_text(p.proposal->'legacy') k
 join public.legacy_category_rejections_v16_2_6 l on l.legacy_key=k.value
 where l.rejection_basis<>'generic_batch_reason' or l.required_action not ilike '%dimensionless%')
 then raise exception 'Legacy exclusion requires separate owner/source review'; end if;
end $legacy$;
insert into public.category_legacy_rejection_resolutions_v16_2_6(category_id,legacy_key,match_type,decision,rationale,reviewed_at)
select p.id,k.value,'exact_title','cleared_for_reconsideration',
'v16.3.4: source-verified dimensionless percentage, with explicit denominator and distinct country-board proof. Meets the legacy ledger exception for comparable dimensionless replacements; not a reinstatement of local-currency totals.',now()
from recovery_proposals p cross join lateral jsonb_array_elements_text(p.proposal->'legacy') k
on conflict(category_id,legacy_key) do update set decision=excluded.decision,rationale=excluded.rationale,reviewed_at=now();

-- Metadata-only completion preserves the original independent value audit.
-- It is not represented as a newly fetched source snapshot.
do $units$
declare p record; v public.stat_category_validation_results; repaired_unit text;
begin
 for p in select * from recovery_proposals where (proposal->>'unitRepair')::boolean loop
  select * into v from public.stat_category_validation_results where category_id=p.id order by validated_at desc,id desc limit 1;
  if v.validation_status<>'failed' or v.value_mismatch_count<>0 or v.ranking_mismatch_count<>0
   or v.source_snapshot_checksum is distinct from v.stored_snapshot_checksum
   or v.metadata_checks->>'unit'<>'false'
   or exists(select 1 from jsonb_each(v.metadata_checks-'unit') kv where kv.value<>'true'::jsonb)
  then raise exception 'Unit-only audit prerequisites failed for %',p.id; end if;
  repaired_unit:=p.proposal->'patch'->>'unit';
  perform public.record_category_validation(p.id,'verified','geostats-v16.3.4-unit-metadata-repair',
   v.common_year,v.expected_observation_count,v.stored_observation_count,v.compared_observation_count,0,0,
   v.source_snapshot_checksum,v.stored_snapshot_checksum,v.metadata_checks||'{"unit":true}'::jsonb,null,
   jsonb_build_object('metadataRepair',true,'previousValidationId',v.id,'previousSourceAuditAt',v.validated_at,
    'newSourceFetch',false,'unit',repaired_unit,'evidence','Official World Bank indicator title and metadata glossary checked on 2026-09-07; source observations are unchanged.',
    'originalAuditDetails',v.details),null);
 end loop;
end $units$;

update public.category_recovery_evidence_v16_3_4 e set
 snapshot_fingerprint=public.category_recovery_fingerprint_v16_3_4(e.category_id),
 dependency_fingerprints=(select jsonb_object_agg(d.id,public.category_recovery_fingerprint_v16_3_4(d.id))
 from (select distinct jsonb_array_elements_text(p->'witness'->'categories') id from jsonb_array_elements(e.proofs) p) d),
 approved=true
where e.category_id in (select id from recovery_proposals);

CREATE OR REPLACE FUNCTION public.refresh_category_ranking_completeness_v16()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '180s'
AS $function$
begin
  delete from public.category_ranking_completeness_v16 where category_id is not null;

  insert into public.category_ranking_completeness_v16(
    category_id,status,reason,observation_count,distinct_value_count,
    top_value_distinct_count,top_value_feasible,assessed_year,assessed_at
  )
  with selected_year as (
    select c.id,c.source_organization,c.ranking_direction,
      coalesce(c.common_year,latest.latest_year)::smallint assessed_year,
      coalesce(c.eligible_universe_type,'universal') universe_type,
      coalesce(c.eligible_country_count,195) eligible_count,
      c.eligible_country_iso3
    from public.stat_categories c
    left join lateral (
      select max(o.data_year)::smallint latest_year
      from public.stat_observations o
      where o.category_id=c.id
    ) latest on c.common_year is null
  ), metrics as (
    select y.*,
      coalesce(s.observation_count,0)::integer observation_count,
      coalesce(s.distinct_value_count,0)::integer distinct_value_count,
      coalesce(t.top_value_distinct_count,0)::integer top_value_distinct_count
    from selected_year y
    left join lateral (
      select count(*)::integer observation_count,
             count(distinct o.value)::integer distinct_value_count
      from public.stat_observations o
      where o.category_id=y.id and o.data_year=y.assessed_year
    ) s on true
    left join lateral (
      select count(distinct top_rows.value)::integer top_value_distinct_count
      from (
        select o.value
        from public.stat_observations o
        where o.category_id=y.id and o.data_year=y.assessed_year
        order by
          case when y.ranking_direction='high' then o.value end desc nulls last,
          case when y.ranking_direction='low' then o.value end asc nulls last,
          o.country_iso3
        limit 20
      ) top_rows
    ) t on true
  )
  select id,
    case
      when assessed_year is null then 'non_comprehensive'
      when universe_type='defined_subset' and eligible_count>=12 and observation_count>=eligible_count
        and (eligible_country_iso3 is null or cardinality(eligible_country_iso3)=eligible_count) then 'comprehensive'
      when observation_count<30 then 'non_comprehensive'
      when observation_count>=185 then 'comprehensive'
      when ranking_direction='low' then 'non_comprehensive'
      when observation_count>=100 and top_value_distinct_count>=10 then 'top_end_complete'
      when source_organization in ('FAOSTAT','FAOSTAT Food Balances','Natural Earth','Pew Research Center','Smithsonian GVP','USGS','UN Comtrade','UNHCR','United Nations','Constitute Project','Inter-Parliamentary Union') and top_value_distinct_count>=10 then 'top_end_complete'
      else 'non_comprehensive' end,
    case
      when assessed_year is null then 'No common comparison year is available.'
      when universe_type='defined_subset' and eligible_count>=12 and observation_count>=eligible_count
        and (eligible_country_iso3 is null or cardinality(eligible_country_iso3)=eligible_count)
        then 'The common-year snapshot covers the complete explicitly defined eligible universe.'
      when observation_count<30 then 'Fewer than 30 countries have comparable observations.'
      when observation_count>=185 then 'The common-year ranking covers nearly the full supported country universe.'
      when ranking_direction='low' then 'Incomplete universal coverage cannot safely support a lowest-wins ranking; define and fully cover a legitimate eligible subset instead of assigning synthetic values.'
      when observation_count>=100 and top_value_distinct_count>=10 then 'The winning end is sufficiently covered and distinct for the universal category.'
      when source_organization in ('FAOSTAT','FAOSTAT Food Balances','Natural Earth','Pew Research Center','Smithsonian GVP','USGS','UN Comtrade','UNHCR','United Nations','Constitute Project','Inter-Parliamentary Union') and top_value_distinct_count>=10
        then 'The source is structurally sparse, but the meaningful winning end contains enough distinct ranked values.'
      else 'One or more omitted countries could plausibly alter the meaningful winning end.' end,
    observation_count,distinct_value_count,top_value_distinct_count,
    (top_value_distinct_count>=10 or (distinct_value_count>=4 and public.category_recovery_ready_v16_3_4(id))),assessed_year,now()
  from metrics;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.refresh_category_semantic_audit_v16_1()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '180s'
AS $function$
begin
  delete from public.category_semantic_audit_v16_1 where category_id is not null;

  insert into public.category_semantic_audit_v16_1(
    category_id,audit_status,source_identity_status,title_unit_status,result_logic_status,
    issues,warnings,assessed_year,observation_count,distinct_value_count,minimum_value,
    maximum_value,top_values,bottom_values,audit_version,assessed_at
  )
  with base as (
    select q.id,q.title,q.effective_title,q.description,q.unit,q.value_type,c.measurement_type,
           q.ranking_direction,q.source_organization,q.source_indicator_code,
           q.editorial_status,q.validation_status,q.validation_reason,
           coalesce(q.validation_mismatch_count,0) as validation_mismatch_count,
           coalesce(q.validation_ranking_mismatch_count,0) as validation_ranking_mismatch_count,
           coalesce(q.common_year,q.latest_available_year)::smallint as assessed_year,
           lower(coalesce(q.unit,'')) as unit_lower,
           lower(coalesce(q.value_type,'')) as value_type_lower,
           lower(coalesce(c.measurement_type,'')) as measurement_type_lower,
           lower(coalesce(q.effective_title,q.title,'')) as title_lower
    from public.category_review_queue_v15 q
    join public.stat_categories c on c.id=q.id
  ), selected as (
    select b.*,o.country_iso3,o.country_name,o.value,o.data_year
    from base b
    left join public.stat_observations o
      on o.category_id=b.id and o.data_year=b.assessed_year
  ), ranked as (
    select s.*,
      row_number() over(partition by s.id order by
        case when s.ranking_direction='high' then s.value end desc nulls last,
        case when s.ranking_direction='low' then s.value end asc nulls last,
        s.country_iso3) as top_rank,
      row_number() over(partition by s.id order by
        case when s.ranking_direction='high' then s.value end asc nulls last,
        case when s.ranking_direction='low' then s.value end desc nulls last,
        s.country_iso3) as bottom_rank
    from selected s
  ), metrics as (
    select b.id,b.title,b.effective_title,b.description,b.unit,b.value_type,b.measurement_type,
      b.ranking_direction,b.source_organization,b.source_indicator_code,b.editorial_status,
      b.validation_status,b.validation_reason,b.validation_mismatch_count,b.validation_ranking_mismatch_count,
      b.assessed_year,b.unit_lower,b.value_type_lower,b.measurement_type_lower,b.title_lower,
      count(r.value)::integer as observation_count,
      count(distinct r.value)::integer as distinct_value_count,
      min(r.value) as minimum_value,max(r.value) as maximum_value,
      coalesce(jsonb_agg(jsonb_build_object(
        'country',r.country_name,'iso3',r.country_iso3,'value',r.value,'year',r.data_year
      ) order by r.top_rank) filter(where r.top_rank<=12 and r.value is not null),'[]'::jsonb) as top_values,
      coalesce(jsonb_agg(jsonb_build_object(
        'country',r.country_name,'iso3',r.country_iso3,'value',r.value,'year',r.data_year
      ) order by r.bottom_rank) filter(where r.bottom_rank<=12 and r.value is not null),'[]'::jsonb) as bottom_values
    from base b left join ranked r on r.id=b.id
    group by b.id,b.title,b.effective_title,b.description,b.unit,b.value_type,b.measurement_type,
      b.ranking_direction,b.source_organization,b.source_indicator_code,b.editorial_status,
      b.validation_status,b.validation_reason,b.validation_mismatch_count,b.validation_ranking_mismatch_count,
      b.assessed_year,b.unit_lower,b.value_type_lower,b.measurement_type_lower,b.title_lower
  ), classified as (
    select m.*,
      (m.value_type_lower like '%percent%' or position('%' in m.unit_lower)>0 or m.unit_lower like '%percent%') as is_percentage,
      (m.unit_lower ~ '(people|persons|sites|animals|tonnes|tons|vehicles|applications|cases|hectares|kilometers|kilometres|square kilometers|square kilometres)') as is_nonnegative_count,
      replace(coalesce(m.source_indicator_code,''),'''','') as clean_code
    from metrics m
  ), findings as (
    select c.*,
      array_remove(array[
        case when c.assessed_year is null then 'No common comparison year is selected.' end,
        case when c.observation_count=0 then 'No observations exist for the selected comparison year.' end,
        case when coalesce(c.source_indicator_code,'')='' then 'Exact official indicator/item/element code is missing.' end,
        case when public.category_v15_true_integrity_failure(
          c.validation_status,c.validation_reason,c.validation_mismatch_count,c.validation_ranking_mismatch_count
        ) then 'Official-source validation found a substantive value, coverage, duplicate, or ranking mismatch.' end,
        case when c.source_indicator_code='PHE_HHAIR_POP_CLEAN_FUELS' then 'Wrong WHO sibling series: population in millions was labeled as a percentage.' end,
        case when c.title_lower like '%clean%cooking%' and c.source_organization='WHO'
                   and c.source_indicator_code<>'PHE_HHAIR_PROP_POP_CLEAN_FUELS'
          then 'Clean-cooking category is not mapped to the official proportion indicator.' end,
        case when c.is_nonnegative_count and c.minimum_value<0
          and not (c.source_organization='United Nations Population Division'
            and c.source_indicator_code ~ '^WPP[0-9]+:(natural-change-rate|net-migration-rate):'
            and c.value_type_lower='rate')
          then format('A count/total category contains a negative value (%s).',c.minimum_value) end,
        case when c.title_lower ~ '^(highest|largest|most|fastest|best) ' and c.ranking_direction='low'
          then 'Title says highest/largest/most but ranking direction is lowest-wins.' end,
        case when c.title_lower ~ '^lowest ' and c.ranking_direction='high'
          then 'Title says lowest but ranking direction is highest-wins.' end,
        case when c.source_organization='FAOSTAT' and c.clean_code ~ ':(5312|5320|5412|5417)$'
                   and c.title_lower ~ '(produced|production|population)'
          then 'FAOSTAT title conflicts with a yield/area/carcass element code.' end,
        case when c.source_organization='FAOSTAT' and c.clean_code ~ ':(5510|5513)$'
                   and c.title_lower ~ '(yield|harvested area|per hectare)'
          then 'FAOSTAT production element is labeled as yield or area.' end,
        case when c.title_lower like '%per person%'
                   and c.measurement_type_lower not in ('per_capita','per capita','per-person','per person')
                   and c.value_type_lower not in ('per_capita','per capita','per-person','per person')
                   and c.unit_lower not like '%per person%'
                   and c.unit_lower not like '%capita%'
                   and lower(c.clean_code) !~ '(\.pc(\.|$)|pcap|per.?capita)'
          then 'Per-person title does not match the stored measurement semantics.' end
      ],null)::text[] as critical_issues,
      array_remove(array[
        case when c.is_percentage and c.title_lower !~ '(share|percentage|percent|%|rate|prevalence|probability|growth|inflation|change)'
          then 'Percentage/rate semantics are not explicit in the player-facing title.' end,
        case when c.is_percentage and (c.minimum_value<0 or c.maximum_value>100)
          then format('Percentage/rate values fall outside 0-100 (min %s, max %s); valid for growth rates, ratios, and percent-of-GDP measures, so verify source semantics rather than auto-block.',c.minimum_value,c.maximum_value) end,
        case when c.is_percentage and c.observation_count>=30 and c.maximum_value between 0 and 1
          then 'All percentage values are at or below 1; verify that fractions were not mislabeled as percentage points.' end,
        case when c.source_organization='FAOSTAT Food Balances' and c.title_lower !~ '(estimated).*(consumption|intake)'
          then 'Food Balance title should describe estimated consumption/intake.' end,
        case when c.title_lower in ('most forest','highest terrestrial and marine protected areas','most stateless people')
          then 'Player-facing title is ambiguous about total/share/residence.' end,
        case when c.source_organization='UN Comtrade' and c.title_lower like '%spice exports%' and c.observation_count>0
          then 'Verify the icon represents the broad spice group rather than peppers alone.' end,
        case when c.distinct_value_count<10 and c.observation_count>=30
          then 'Fewer than ten distinct values exist in the selected-year results.' end
      ],null)::text[] as audit_warnings
    from classified c
  )
  select id,
    case
      when editorial_status in ('rejected','duplicate') then 'excluded'
      when cardinality(critical_issues)>0 then 'data_repair_required'
      when cardinality(audit_warnings)>0 and (
        title_lower in ('most forest','highest terrestrial and marine protected areas','most stateless people')
        or (is_percentage and title_lower ~ '^(highest|largest|most) ' and title_lower !~ '(share|percentage|percent|%|rate|prevalence|probability|growth|inflation|change)')
        or (source_organization='FAOSTAT Food Balances' and title_lower !~ '(estimated).*(consumption|intake)')
      ) then 'rewrite_required'
      when coalesce(source_indicator_code,'')='' then 'review_required'
      when is_percentage and observation_count>=30 and maximum_value between 0 and 1 then 'review_required'
      else 'pass'
    end,
    case
      when source_indicator_code='PHE_HHAIR_POP_CLEAN_FUELS' then 'mismatch'
      when public.category_v15_true_integrity_failure(
        validation_status,validation_reason,validation_mismatch_count,validation_ranking_mismatch_count
      ) then 'mismatch'
      when coalesce(source_indicator_code,'')='' then 'incomplete'
      else 'identified'
    end,
    case
      when cardinality(audit_warnings)>0 then 'warning'
      else 'aligned'
    end,
    case
      when cardinality(critical_issues)>0 then 'blocked'
      when observation_count=0 then 'blocked'
      else 'plausibility_screen_passed'
    end,
    critical_issues,audit_warnings,assessed_year,observation_count,distinct_value_count,
    minimum_value,maximum_value,top_values,bottom_values,
    'geostats-v16.2.6-semantic-audit-v2',now()
  from findings;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.refresh_category_promotion_assessment_v16_2()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '180s'
AS $function$
begin
  perform public.apply_category_recovery_credibility_v16_3_4();
  delete from public.category_promotion_assessment_v16_2 where category_id is not null;

  insert into public.category_promotion_assessment_v16_2(
    category_id,current_editorial_status,proposed_status,blocker_class,
    primary_blocker,reason,strict_pass,source_quality_floor,suggested_duplicate_of,assessed_at
  )
  with base as (
    select
      v.*,
      c.eligible_universe_type,
      c.eligible_universe_rule,
      c.eligible_country_count,
      c.eligible_country_iso3,
      c.coverage_within_eligible_universe,
      c.excluded_country_reason,
      public.category_v16_2_quality_floor(v.source_organization) as source_floor,
      public.category_v15_true_integrity_failure(
        v.validation_status,v.validation_reason,
        v.validation_mismatch_count,v.validation_ranking_mismatch_count
      ) as true_integrity_failure,
      public.category_v16_2_copy_is_clear(
        v.effective_title,coalesce(v.plain_language_description,v.description),
        v.unit,v.source_indicator_code
      ) as copy_clear,
      case
        when nullif(trim(coalesce(v.source_indicator_code,'')),'') is not null then
          'series|'||lower(coalesce(v.source_organization,''))||'|'||lower(v.source_indicator_code)||'|'||coalesce(v.ranking_direction,'high')
        else
          'title|'||regexp_replace(lower(coalesce(v.effective_title,'')),'[^a-z0-9]+','','g')||'|'||lower(coalesce(v.unit,''))||'|'||coalesce(v.ranking_direction,'high')
      end as exact_duplicate_key,
      (
        v.semantic_audit_status='pass'
        and v.ranking_completeness_status in ('comprehensive','top_end_complete')
        and coalesce(v.top_value_feasible,false)
        and not public.category_v15_true_integrity_failure(
          v.validation_status,v.validation_reason,
          v.validation_mismatch_count,v.validation_ranking_mismatch_count
        )
        and (
          v.validation_status='verified'
          or (
            v.validation_status='unable_to_verify'
            and coalesce(v.validation_reason,'') ilike 'Non-blocking audit warning:%'
          )
        )
        and (coalesce(v.quality_score,0)>=public.category_v16_2_quality_floor(v.source_organization) or public.category_recovery_quality_exception_v16_3_4(v.id))
        and coalesce(v.credibility_status,'approved')<>'quarantined'
        and coalesce(v.credibility_score,75)>=70
        and (
          case when coalesce(c.eligible_universe_type,'universal')='defined_subset' then
            coalesce(c.eligible_country_count,0)>=12
            and (
              coalesce(c.eligible_country_count,0)>=16
              or coalesce(v.metadata->>'eligibleUniverseExceptionApproved','false')='true'
            )
            and greatest(coalesce(v.common_year_coverage,0),coalesce(v.country_coverage,0))>=coalesce(c.eligible_country_count,0)
            and (
              c.eligible_country_iso3 is null
              or cardinality(c.eligible_country_iso3)=c.eligible_country_count
            )
          else greatest(coalesce(v.common_year_coverage,0),coalesce(v.country_coverage,0))>=30
          end
        )
        and not coalesce(v.stale_data,false)
        and v.player_source_status in ('exact','general')
        and public.player_source_url_is_safe(v.player_source_url)
        and coalesce(v.objective_status,'objective')='objective'
        and coalesce(v.player_quality_status,'approved')<>'blocked'
        and coalesce(v.content_review_status,'pending')<>'excluded'
        and coalesce(v.curation_status,'pending')<>'excluded'
        and (
          v.content_review_status='approved'
          or (
            coalesce(v.immediate_comprehension_score,0)>=85
            and coalesce(v.gameplay_interest_score,0)>=70
            and coalesce(v.uniqueness_score,0)>=65
          )
        )
        and public.category_v16_2_copy_is_clear(
          v.effective_title,coalesce(v.plain_language_description,v.description),
          v.unit,v.source_indicator_code
        )
        and not coalesce(v.political_self_reported,false)
        and not coalesce(v.confusing,false)
        and not coalesce(v.esoteric,false)
        and not coalesce(v.subjective_or_composite,false)
        and not coalesce(v.poor_coverage,false)
        and v.duplicate_of is null
        -- v16.2.6 recovery: do not ban an entire provider. v16.2.5 already
        -- removed the legacy UNESCO UIS / U.S. EIA blanket exclusion; 048
        -- accidentally reintroduced it. Row-level validation and editorial
        -- gates remain fully enforced below.
        and lower(coalesce(v.effective_title,'')) !~ '(yield|harvested area|carcass|slaughter|producing animals|output per worker|employment.?to.?population|labor.?income share)'
      ) as strict_pass
    from public.category_runtime_review_v16 v
    join public.stat_categories c on c.id=v.id
  ), ranked as (
    select b.*,
      count(*) over(partition by exact_duplicate_key) as exact_duplicate_count,
      first_value(id) over(
        partition by exact_duplicate_key
        order by
          case when editorial_status='approved' then 0 else 1 end,
          case when validation_status='verified' then 0 else 1 end,
          coalesce(quality_score,0) desc,
          id
      ) as preferred_exact_duplicate_id
    from base b
  ), assessed as (
    select r.*,case
      when exact_duplicate_count>1 and id<>preferred_exact_duplicate_id then preferred_exact_duplicate_id
      else null
    end as detected_duplicate_of
    from ranked r
  )
  select
    id,
    editorial_status,
    case
      when editorial_status='duplicate' or duplicate_of is not null or detected_duplicate_of is not null then 'duplicate'
      when editorial_status='rejected' then 'excluded'
      when semantic_audit_status='data_repair_required' or true_integrity_failure then 'data_repair_required'
      when semantic_audit_status='rewrite_required' or not copy_clear then 'rewrite_required'
      when strict_pass and editorial_status='approved' then 'playable'
      when strict_pass and editorial_status in ('pending','needs_rewrite') then 'auto_promote'
      else 'manual_review'
    end,
    case
      when editorial_status='duplicate' or duplicate_of is not null or detected_duplicate_of is not null then 'duplicate'
      when editorial_status='rejected' then 'editorial_exclusion'
      when semantic_audit_status='data_repair_required' or true_integrity_failure then 'substantive_data_failure'
      when semantic_audit_status='rewrite_required' or not copy_clear then 'copy_or_semantic_rewrite'
      when strict_pass and editorial_status in ('approved','pending','needs_rewrite') then 'strict_automatic_pass'
      when validation_status not in ('verified','unable_to_verify')
        or (validation_status='unable_to_verify' and coalesce(validation_reason,'') not ilike 'Non-blocking audit warning:%')
        then 'source_audit_pending'
      when semantic_audit_status<>'pass' then 'semantic_review'
      when ranking_completeness_status not in ('comprehensive','top_end_complete') or not coalesce(top_value_feasible,false) then 'ranking_completeness'
      when coalesce(quality_score,0)<source_floor then 'source_specific_quality'
      when content_review_status<>'approved' then 'editorial_content_review'
      else 'manual_editorial_review'
    end,
    case
      when detected_duplicate_of is not null then 'Exact duplicate of preferred category '||detected_duplicate_of||'.'
      when editorial_status='duplicate' or duplicate_of is not null then 'Marked as a duplicate of another category.'
      when editorial_status='rejected' then 'Deliberately excluded by editorial policy.'
      when semantic_audit_status='data_repair_required' then 'Semantic audit identified a substantive data repair.'
      when true_integrity_failure then coalesce(validation_reason,'Official-source values or rankings do not match the stored data.')
      when semantic_audit_status='rewrite_required' or not copy_clear then 'Player-facing title, description, or unit needs a clearer rewrite.'
      when strict_pass and editorial_status='approved' then null
      when strict_pass then null
      when validation_status not in ('verified','unable_to_verify') then 'Official-source value and ranking audit has not completed.'
      when validation_status='unable_to_verify' and coalesce(validation_reason,'') not ilike 'Non-blocking audit warning:%' then coalesce(validation_reason,'Official-source audit could not verify this category.')
      when semantic_audit_status<>'pass' then 'Semantic audit has not passed.'
      when ranking_completeness_status not in ('comprehensive','top_end_complete') then coalesce(ranking_completeness_reason,'Ranking completeness has not passed.')
      when not coalesce(top_value_feasible,false) then 'The meaningful top values are not distinct enough for a GeoStats board.'
      when coalesce(quality_score,0)<source_floor then 'Below the source-specific quality floor.'
      when coalesce(eligible_universe_type,'universal')='defined_subset' and coalesce(eligible_country_count,0)<12 then 'Defined subset has fewer than 12 eligible countries.'
      when coalesce(eligible_universe_type,'universal')='defined_subset' and coalesce(eligible_country_count,0)<16 and coalesce(metadata->>'eligibleUniverseExceptionApproved','false')<>'true' then 'A 12–15-country subset requires explicit board-feasibility/editorial exception approval.'
      when coalesce(eligible_universe_type,'universal')='defined_subset' and greatest(coalesce(common_year_coverage,0),coalesce(country_coverage,0))<coalesce(eligible_country_count,0) then 'The common-year snapshot is incomplete across the declared eligible universe.'
      when coalesce(eligible_universe_type,'universal')='defined_subset' and eligible_country_iso3 is not null and cardinality(eligible_country_iso3)<>eligible_country_count then 'Eligible-country list and declared universe size disagree.'
      when coalesce(eligible_universe_type,'universal')<>'defined_subset' and greatest(coalesce(common_year_coverage,0),coalesce(country_coverage,0))<30 then 'Fewer than 30 comparable country values are available.'
      when coalesce(objective_status,'objective')<>'objective' then 'The measure is not classified as objective.'
      when coalesce(player_quality_status,'approved')='blocked' then coalesce(player_quality_reason,'Player-quality review blocked the category.')
      when content_review_status<>'approved' then coalesce(content_review_reason,'Content review is not approved and automatic clarity scores are insufficient.')
      else 'Requires a human editorial decision.'
    end,
    case
      when detected_duplicate_of is not null then 'Keep blocked as an exact duplicate of preferred category '||detected_duplicate_of||'.'
      when editorial_status='duplicate' or duplicate_of is not null then 'Keep blocked as a duplicate of the preferred category.'
      when strict_pass and editorial_status='approved' then 'Already approved and passes the v16.2 source-specific, semantic, ranking, clarity, and board-feasibility gates.'
      when strict_pass then 'Auto-approve: objective official-source measure; semantic identity, bounds, rankings, coverage, clarity, and board feasibility all pass.'
      when semantic_audit_status='data_repair_required' or true_integrity_failure then 'Keep blocked until source values, dimensions, year, coverage, or rankings are repaired and re-audited.'
      when semantic_audit_status='rewrite_required' or not copy_clear then 'Keep blocked until player-facing copy accurately distinguishes totals, shares, rates, per-person measures, residence, and origin.'
      else 'Do not auto-approve; retain for focused manual review.'
    end,
    strict_pass and detected_duplicate_of is null,
    source_floor,
    detected_duplicate_of,
    now()
  from assessed;
end;
$function$
;
CREATE OR REPLACE VIEW public.category_runtime_review_v16_2 AS  SELECT v.id,
    v.title,
    v.short_title,
    v.description,
    v.icon,
    v.unit,
    v.value_type,
    v.ranking_direction,
    v.family,
    v.source_organization,
    v.source_dataset,
    v.source_indicator_code,
    v.source_url,
    v.enabled,
    v.minimum_year,
    v.latest_available_year,
    v.country_coverage,
    v.metadata,
    v.created_at,
    v.updated_at,
    v.quality_score,
    v.eligible_daily,
    v.quality_details,
    v.review_status,
    v.evidence_tier,
    v.auto_qualified,
    v.common_year,
    v.common_year_coverage,
    v.official_observation_share,
    v.modeled_observation_share,
    v.clustering_score,
    v.stability_score,
    v.methodology_notes,
    v.quality_standard_version,
    v.canonical_category_id,
    v.canonical_match_status,
    v.canonical_match_score,
    v.recognizability_score,
    v.specificity_score,
    v.provenance_status,
    v.provenance_class,
    v.provenance_reason,
    v.methodology_url,
    v.independent_validation,
    v.government_assertion_risk,
    v.concept_group,
    v.governance_priority,
    v.governance_version,
    v.duplicate_status,
    v.superseded_by,
    v.auto_decision_reason,
    v.curation_status,
    v.curation_reason,
    v.curation_version,
    v.credibility_score,
    v.credibility_status,
    v.credibility_reason,
    v.evidence_label,
    v.comparability_risk,
    v.corroboration_status,
    v.plain_language_description,
    v.technical_definition,
    v.unit_explanation,
    v.source_page_url,
    v.exact_query_url,
    v.download_url,
    v.api_url,
    v.dataset_release,
    v.retrieved_at,
    v.license_name,
    v.license_url,
    v.source_query,
    v.derivation_method,
    v.derivation_version,
    v.input_datasets,
    v.verifiability_score,
    v.verifiability_status,
    v.understandability_score,
    v.fun_score,
    v.objective_status,
    v.player_quality_status,
    v.player_quality_reason,
    v.validation_status,
    v.validation_version,
    v.validated_at,
    v.validation_reason,
    v.source_snapshot_checksum,
    v.stored_snapshot_checksum,
    v.validated_observation_count,
    v.validation_expected_count,
    v.validation_mismatch_count,
    v.validation_ranking_mismatch_count,
    v.semantic_family,
    v.semantic_topic,
    v.player_source_url,
    v.player_source_status,
    v.player_source_reason,
    v.player_source_checked_at,
    v.content_review_status,
    v.content_review_reason,
    v.content_review_version,
    v.immediate_comprehension_score,
    v.gameplay_interest_score,
    v.uniqueness_score,
    v.link_quality_score,
    v.editorial_status,
    v.political_self_reported,
    v.confusing,
    v.esoteric,
    v.subjective_or_composite,
    v.stale_data,
    v.poor_coverage,
    v.duplicate_of,
    v.recommended_title,
    v.semantic_group,
    v.editorial_notes,
    v.reviewed_by,
    v.reviewed_at,
    v.editorial_updated_at,
    v.effective_title,
    v.effective_semantic_group,
    v.hard_gate_ready,
    v.editorial_ready,
    v.computed_playable_v15,
    v.v15_blockers,
    v.source_link_ready,
    v.v15_warnings,
    v.ranking_completeness_status,
    v.ranking_completeness_reason,
    v.top_value_distinct_count,
    v.top_value_feasible,
    v.computed_playable_v16,
    v.v16_blockers,
    v.v16_warnings,
    v.semantic_audit_status,
    v.semantic_source_identity_status,
    v.semantic_title_unit_status,
    v.semantic_result_logic_status,
    v.semantic_audit_issues,
    v.semantic_audit_warnings,
    v.semantic_top_values,
    v.semantic_bottom_values,
    a.proposed_status AS promotion_decision_v16_2,
    a.reason AS promotion_reason_v16_2,
    a.primary_blocker AS primary_blocker_v16_2,
    a.blocker_class AS blocker_class_v16_2,
    a.strict_pass AS strict_pass_v16_2,
    a.source_quality_floor AS source_quality_floor_v16_2,
    a.suggested_duplicate_of AS suggested_duplicate_of_v16_2,
    a.proposed_status = 'playable'::text AND v.editorial_status = 'approved'::text AND a.strict_pass AND category_v16_2_6_hard_block_reason(c.id, c.source_organization, c.source_indicator_code, v.effective_title, c.metadata) IS NULL AND cardinality(legacy.blockers) = 0 AND (NOT EXISTS (SELECT 1 FROM public.category_recovery_evidence_v16_3_4 re WHERE re.category_id=v.id) OR public.category_recovery_ready_v16_3_4(v.id)) AS computed_playable_v16_2,
    array_remove(ARRAY[
        CASE
            WHEN a.proposed_status <> 'playable'::text THEN a.primary_blocker
            ELSE NULL::text
        END, category_v16_2_6_hard_block_reason(c.id, c.source_organization, c.source_indicator_code, v.effective_title, c.metadata),
        CASE
            WHEN cardinality(legacy.blockers) > 0 THEN 'legacy_rejection_reaudit'::text
            ELSE NULL::text
        END], NULL::text) AS v16_2_blockers,
    array_remove(ARRAY[
        CASE
            WHEN v.validation_status <> 'verified'::text AND NOT category_v15_true_integrity_failure(v.validation_status, v.validation_reason, v.validation_mismatch_count, v.validation_ranking_mismatch_count) THEN 'Official values are usable; non-data source metadata remain incomplete.'::text
            ELSE NULL::text
        END,
        CASE
            WHEN v.ranking_completeness_status = 'top_end_complete'::text THEN 'Ranking is top-end complete rather than fully comprehensive.'::text
            ELSE NULL::text
        END,
        CASE
            WHEN v.player_source_status = 'general'::text THEN 'Uses a general official source page rather than an exact shareable view.'::text
            ELSE NULL::text
        END], NULL::text) AS v16_2_warnings,
    c.measurement_type,
    c.eligible_universe_type,
    c.eligible_universe_rule,
    c.eligible_country_count,
    c.eligible_country_iso3,
    c.coverage_within_eligible_universe,
    c.excluded_country_reason,
    legacy.blockers AS legacy_rejection_blockers_v16_2_6
   FROM category_runtime_review_v16 v
     JOIN category_promotion_assessment_v16_2 a ON a.category_id = v.id
     JOIN stat_categories c ON c.id = v.id
     CROSS JOIN LATERAL ( SELECT category_legacy_rejection_blockers_v16_2_6(c.id, v.effective_title) AS blockers) legacy;

-- This boolean exposes only public category readiness and is needed by the public view.
grant execute on function public.category_recovery_ready_v16_3_4(text) to anon,authenticated;
insert into public.generator_reachability_v16_2_7(category_id,difficulty,reachable,failure_stage,detail,audit_version,checked_at)
select e.category_id,p->>'difficulty',true,null,
jsonb_build_object('witness',p->'witness','snapshotFingerprint',e.snapshot_fingerprint,'rulesVersion',e.rules_version,'auditFingerprint',p->>'fingerprint')::text,
'geostats-v16.3.4-production-solver-v1',now()
from public.category_recovery_evidence_v16_3_4 e cross join lateral jsonb_array_elements(e.proofs) p
on conflict(category_id,difficulty) do update set reachable=true,failure_stage=null,detail=excluded.detail,audit_version=excluded.audit_version,checked_at=excluded.checked_at;

select public.refresh_v16_2_runtime_catalog();

do $accept$
declare problems jsonb;
begin
 if exists(select 1 from recovery_baseline b left join public.category_runtime_review_v16_2 v on v.id=b.id where not coalesce(v.computed_playable_v16_2,false))
 then raise exception 'Recovery would remove an existing playable category'; end if;
 select jsonb_agg(jsonb_build_object('id',v.id,'blockers',v.v16_2_blockers,'status',v.editorial_status,
 'proofCurrent',public.category_recovery_ready_v16_3_4(v.id),'semantic',v.semantic_audit_issues,'quality',v.quality_score,
 'credibility',v.credibility_score)) into problems
 from recovery_proposals p join public.category_runtime_review_v16_2 v on v.id=p.id
 where not v.computed_playable_v16_2 or not v.enabled or not v.eligible_daily;
 if problems is not null then raise exception 'Recovery acceptance failed: %',problems; end if;
 if (select count(*) from public.category_runtime_review_v16_2 where computed_playable_v16_2)<>385
 then raise exception 'Unexpected catalog growth outside 67 reviewed candidates'; end if;
 perform public.assert_v16_3_4_runtime_catalog();
end $accept$;
commit;

